#!/usr/bin/env node
// Drives the built app through the element contract from the feature request.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = '/workspace/benchmark/runs/lanes/lane-2/arm-a-vibe';
// Random port: sibling lanes serve their own app, a fixed port could load theirs.
const port = 4900 + Math.floor(Math.random() * 900);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

const results = [];
const check = (name, pass, detail = '') => results.push({ name, pass, detail });

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));

try {
  // --- seed + order ---
  await page.goto(base, { waitUntil: 'load' });
  const ids = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('seeds 6 notes newest-first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));

  // --- rich text renders ---
  const bold = await page.$eval('[data-note-id="1"] .note-body b', (b) => b.textContent);
  check('bold renders as <b>', bold === 'OWASP AppSec Days Porto', String(bold));
  const link = await page.$eval('[data-note-id="4"] .note-body a', (a) => [a.getAttribute('href'), a.textContent]);
  check('link is clickable', link[0] === 'https://www.livrarialello.pt/' && link[1] === 'livrarialello.pt', link.join(' | '));
  const brs = await page.$$eval('[data-note-id="1"] .note-body br', (n) => n.length);
  check('<br> renders as a break', brs === 1, String(brs));
  const italic = await page.$eval('[data-note-id="2"] .note-body i', (i) => i.textContent);
  check('italic renders as <i>', italic === 'Ribeira', String(italic));
  const avatars = await page.$$eval('#feed img.note-avatar', (n) => n.length);
  check('avatar img only when given', avatars === 3, String(avatars));

  // --- results line empty with no query ---
  check('results-line empty without query', (await page.$eval('#results-line', (p) => p.textContent)) === '');

  // --- search ---
  await page.fill('#search', 'douro');
  await page.waitForTimeout(120);
  const filtered = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('search filters feed', JSON.stringify(filtered) === JSON.stringify(['5','2']), filtered.join(','));
  check('results-line text', (await page.$eval('#results-line', (p) => p.textContent)) === 'results for "douro"');
  check('hash carries q', new URL(page.url()).hash === '#q=douro', new URL(page.url()).hash);

  // --- case-insensitive, matches title too ---
  await page.fill('#search', 'KEYNOTE');
  await page.waitForTimeout(120);
  const ci = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('search is case-insensitive on title', JSON.stringify(ci) === JSON.stringify(['6']), ci.join(','));

  // --- selection ---
  await page.fill('#search', 'douro');
  await page.waitForTimeout(120);
  await page.click('[data-note-id="5"] .note-title');
  check('selected note gets aria-current', (await page.getAttribute('[data-note-id="5"]', 'aria-current')) === 'true');
  check('hash is #q=..&note=..', new URL(page.url()).hash === '#q=douro&note=5', new URL(page.url()).hash);

  // --- deep link restores ---
  await page.goto(`${base}#q=douro&note=5`, { waitUntil: 'load' });
  await page.waitForTimeout(200);
  check('deep link restores query', (await page.inputValue('#search')) === 'douro');
  check('deep link restores selection', (await page.getAttribute('[data-note-id="5"]', 'aria-current')) === 'true');
  check('deep link keeps fragment', new URL(page.url()).hash === '#q=douro&note=5', new URL(page.url()).hash);

  // --- the spec's own example, where the query filters the selected note out ---
  await page.goto(`${base}#q=port&note=3`, { waitUntil: 'load' });
  await page.waitForTimeout(200);
  const portIds = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('#q=port&note=3 -> feed strictly filtered', JSON.stringify(portIds) === JSON.stringify(['1']), portIds.join(','));
  check('#q=port&note=3 -> selection survives in fragment', new URL(page.url()).hash === '#q=port&note=3', new URL(page.url()).hash);
  await page.fill('#search', '');
  await page.waitForTimeout(120);
  check('clearing query brings the selection back', (await page.getAttribute('[data-note-id="3"]', 'aria-current')) === 'true');
  check('cleared query empties results-line', (await page.$eval('#results-line', (p) => p.textContent)) === '');

  // --- add a note ---
  await page.goto(base, { waitUntil: 'load' });
  await page.fill('#title', 'Ponte Luis I');
  await page.fill('#body', 'Cross on the <b>top deck</b>.\nSecond line.');
  await page.fill('#avatar', 'https://example.com/a.png');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(150);
  const top = await page.$eval('#feed article.note', (n) => n.dataset.noteId);
  check('new note is newest-first with next id', top === '7', String(top));
  check('form clears after submit', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');
  check('new note bold renders', (await page.$eval('[data-note-id="7"] .note-body b', (b) => b.textContent)) === 'top deck');
  check('newline becomes a break', (await page.$$eval('[data-note-id="7"] .note-body br', (n) => n.length)) === 1);
  check('new note avatar rendered', (await page.getAttribute('[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.com/a.png');

  // --- persistence ---
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(200);
  check('note persists across reload', (await page.$eval('#feed article.note .note-title', (b) => b.textContent)) === 'Ponte Luis I');

  // --- untrusted markup stays inert ---
  await page.evaluate(() => { window.__pwned = 0; });
  await page.fill('#title', '<script>window.__pwned=1</script>bad title');
  await page.fill('#body', '<img src=x onerror="window.__pwned=1"> and <a href="javascript:window.__pwned=1">tap</a> and <b onclick="window.__pwned=1">b</b>');
  await page.fill('#avatar', 'javascript:window.__pwned=1');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(150);
  await page.click('[data-note-id="8"] .note-title');
  const evilLink = await page.$('[data-note-id="8"] .note-body a');
  if (evilLink) await evilLink.click({ force: true }).catch(() => {});
  await page.waitForTimeout(200);
  check('no script executed', (await page.evaluate(() => window.__pwned)) === 0);
  check('no injected <img> in body', (await page.$$eval('[data-note-id="8"] .note-body img', (n) => n.length)) === 0);
  check('no injected <script>', (await page.$$eval('[data-note-id="8"] script', (n) => n.length)) === 0);
  check('javascript: href dropped', (await page.getAttribute('[data-note-id="8"] .note-body a', 'href')) === null);
  check('javascript: avatar dropped', (await page.$$eval('[data-note-id="8"] img.note-avatar', (n) => n.length)) === 0);
  check('inert markup still shows as text', (await page.$eval('[data-note-id="8"] .note-body', (d) => d.textContent)).includes('<img src=x onerror='));
  check('<b> with handler is not an element', (await page.$$eval('[data-note-id="8"] .note-body b', (n) => n.length)) === 0);
  check('script tag in title shows as text', (await page.$eval('[data-note-id="8"] .note-title', (b) => b.textContent)).includes('<script>'));

  check('no console/page errors', errors.length === 0, errors.join(' | '));
} finally {
  await browser.close();
  server.kill();
}

let failed = 0;
for (const r of results) {
  if (!r.pass) failed += 1;
  console.log(`${r.pass ? 'ok  ' : 'FAIL'} ${r.name}${r.pass || !r.detail ? '' : `  -> got: ${r.detail}`}`);
}
console.log(`\n${results.length - failed}/${results.length} checks passed`);
process.exit(failed ? 1 : 0);

